(function(){"use strict";tinymce.PluginManager.add("codesource",function(editor,url){let cmInstance=null;const formatHTML=function(html){const protectedBlocks=[];let safeHtml=html.replace(/(<(pre|script|style|textarea)[^>]*>)([\s\S]*?)(<\/\2>)/gi,function(match){protectedBlocks.push(match);return"\n___PROTECTED_BLOCK_"+(protectedBlocks.length-1)+"___\n"});let indentLevel=0;let formatted=safeHtml.replace(/>\s*</g,">\n<").split("\n").map(function(line){line=line.trim();if(!line)return"";if(line.match(/^___PROTECTED_BLOCK_\d+___$/)){return"  ".repeat(indentLevel)+line}if(line.match(/^<\/(?!html)/)){indentLevel=Math.max(0,indentLevel-1)}const formattedLine="  ".repeat(indentLevel)+line;if(line.match(/^<(?!\/|!--|img|br|hr|input|meta|link|area|base|col|param|source|track|embed|wbr)[^>]+>$/)&&!line.endsWith("/>")){indentLevel++}return formattedLine}).join("\n");protectedBlocks.forEach(function(block,index){formatted=formatted.replace("___PROTECTED_BLOCK_"+index+"___",block)});return formatted};const injectStyles=function(){const styleId="cm6-tinymce-modal-style";if(!document.getElementById(styleId)){const style=document.createElement("style");style.id=styleId;style.textContent=`\n          .tox-dialog__body-content:has(#cm-editor-modal) {\n            padding: 0 !important;\n            overflow: hidden !important; /* Coupe l'ascenseur inactif de TinyMCE */\n            position: relative !important; /* Point d'ancrage pour le positionnement absolu */\n          }\n          #cm-editor-modal {\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            bottom: 0;\n            background-color: #ffffff;\n          }\n        `;document.head.appendChild(style)}};const ensureDependencies=function(callback){if(window.CM6&&window.CM6.openSearchPanel){callback();return}const script=document.createElement("script");script.type="text/javascript";script.src=url+"/codemirror.bundle.js?v=1.1";script.onload=callback;script.onerror=function(){editor.notificationManager.open({text:"Échec du chargement de CodeMirror 6",type:"error"})};document.head.appendChild(script)};const openEditorDialog=function(){ensureDependencies(function(){injectStyles();const{EditorView:EditorView,EditorState:EditorState,basicSetup:basicSetup,html:html,oneDark:oneDark,openSearchPanel:openSearchPanel}=window.CM6;editor.windowManager.open({title:"Code source HTML",size:"large",body:{type:"panel",items:[{type:"htmlpanel",html:'<div id="cm-editor-modal"></div>'}]},buttons:[{type:"cancel",name:"cancel",text:"Annuler"},{type:"custom",name:"search",text:"Rechercher",icon:"search"},{type:"submit",name:"save",text:"Enregistrer",primary:true}],onAction:function(api,details){if(details.name==="search"&&cmInstance){openSearchPanel(cmInstance)}},onSubmit:function(api){if(cmInstance){const updatedContent=cmInstance.state.doc.toString();editor.setContent(updatedContent);cmInstance.destroy();cmInstance=null}api.close()},onClose:function(){if(cmInstance){cmInstance.destroy();cmInstance=null}}});setTimeout(function(){try{const container=document.getElementById("cm-editor-modal");if(!container)return;const shadowRoot=container.attachShadow({mode:"open"});const rawCode=editor.getContent({source_view:true});const beautifulCode=formatHTML(rawCode);const customTheme=EditorView.theme({"&":{height:"100%",fontSize:"14px",fontFamily:"Menlo, Monaco, Consolas, 'Courier New', monospace",backgroundColor:"#ffffff",color:"#333333"},".cm-scroller":{overflow:"auto"},"&.cm-focused":{outline:"none"},".cm-gutters":{backgroundColor:"#f5f5f5",color:"#999999",borderRight:"1px solid #dddddd"}});cmInstance=new EditorView({state:EditorState.create({doc:beautifulCode,extensions:[basicSetup,html(),customTheme,EditorView.lineWrapping]}),parent:shadowRoot});setTimeout(()=>cmInstance.focus(),50)}catch(e){console.error("CodeSource ERREUR FATALE :",e)}},50)})};editor.addCommand("mceCodeSource",openEditorDialog);editor.ui.registry.addButton("codesource",{icon:"sourcecode",tooltip:"Code source (CodeMirror 6)",onAction:()=>editor.execCommand("mceCodeSource")});editor.ui.registry.addMenuItem("codesource",{icon:"sourcecode",text:"Code source...",onAction:()=>editor.execCommand("mceCodeSource")});return{getMetadata:function(){return{name:"CodeSource CodeMirror 6",url:"https://github.com/gtraxx/tinymce-codesource",author:"Aurélien Gérits (Magix CMS)"}}}})})();